package com.carebridge.backend.partner.controller;
import com.carebridge.backend.partner.service.PartnerApprovalService;import com.carebridge.backend.partner.dto.request.PartnerDecisionRequest;import com.carebridge.backend.partner.dto.response.PartnerDecisionResponse;import com.carebridge.backend.common.response.ApiResponse;import com.carebridge.backend.common.util.SecurityUtils;import jakarta.validation.Valid;import java.security.Principal;import java.util.UUID;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/partners") @PreAuthorize("hasRole('SYSTEM_ADMIN')") @RequiredArgsConstructor public class PartnerApprovalController{private final PartnerApprovalService service;@PostMapping("/{partnerId}/decision")public ResponseEntity<ApiResponse<PartnerDecisionResponse>> decide(@PathVariable UUID partnerId,@Valid @RequestBody PartnerDecisionRequest request,Principal principal){return ResponseEntity.ok(ApiResponse.success(service.decide(partnerId,request,SecurityUtils.requireCurrentUserId(principal)),"Partner decision applied successfully"));}}
